SELECT ,
       CONTENT
  FROM SCRAPED_LAW_CONTENTS
 WHERE SOURCE_TYPE = #{sourceType}
   AND EXTERNAL_ID = #{externalId}

SELECT * FROM (
    SELECT ID
      FROM SCRAPED_LAW_CONTENTS


            SOURCE_TYPE = #{sourceType}

        AND ( INSTR(NAME, #{query}) > 0
              OR (CONTENT IS NOT NULL AND DBMS_LOB.INSTR(CONTENT, #{query}) > 0) )

     ORDER BY NAME
) WHERE ROWNUM <= #{limit}

SELECT , CONTENT FROM SCRAPED_LAW_CONTENTS WHERE ID IN
#{id}
ORDER BY NAME
